package dev.gbppimentel.zzz;
import android.content.Context;import android.graphics.*;import java.net.*;import java.io.*;import org.json.*;
/** Public combat portraits are fetched without account cookies, then reduced to local features. */
final class PortraitModelStore {
 static void update(Context c,JSONArray roster)throws Exception{if(roster==null)return;StringBuilder sourceKey=new StringBuilder(PortraitFeatures.VERSION+";");for(int i=0;i<roster.length();i++){JSONObject a=roster.getJSONObject(i);sourceKey.append(a.optInt("id")).append(':').append(a.optString("hollow_icon_path")).append(';');}String signature=sourceKey.toString();android.content.SharedPreferences prefs=c.getSharedPreferences("eridu",0);if(signature.equals(prefs.getString("portrait-source",""))&&new File(c.getFilesDir(),"portraits.dynamic.json").exists())return;JSONArray models;try(InputStream in=c.getAssets().open("portraits.json")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);models=new JSONArray(b.toString("UTF-8"));}int success=0;
  for(int i=0;i<roster.length();i++){if(Thread.currentThread().isInterrupted())return;JSONObject a=roster.getJSONObject(i);String address=a.optString("hollow_icon_path");try{URL url=new URL(address);if(!url.getProtocol().equals("https")||!url.getHost().equals("act-webstatic.hoyoverse.com"))continue;HttpURLConnection conn=(HttpURLConnection)url.openConnection();conn.setConnectTimeout(7000);conn.setReadTimeout(7000);conn.setInstanceFollowRedirects(false);try{if(conn.getResponseCode()!=200)continue;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>2000000)throw new IOException("Portrait too large");bytes.write(b,0,n);}}byte[] raw=bytes.toByteArray();Bitmap original=BitmapFactory.decodeByteArray(raw,0,raw.length);if(original==null)continue;int[] pixels=new int[original.getWidth()*original.getHeight()];original.getPixels(pixels,0,original.getWidth(),0,0,original.getWidth(),original.getHeight());PortraitFeatures.append(models,Integer.toString(a.optInt("id")),pixels,original.getWidth(),original.getHeight());original.recycle();success++;}finally{conn.disconnect();}}catch(Exception ignored){}}
  File next=new File(c.getFilesDir(),"portraits.dynamic.next"),dest=new File(c.getFilesDir(),"portraits.dynamic.json");try(FileOutputStream out=new FileOutputStream(next)){out.write(models.toString().getBytes("UTF-8"));}if(!next.renameTo(dest))throw new IOException("Portrait features unavailable");if(success==roster.length())prefs.edit().putString("portrait-source",signature).apply();
 }
}
